type NetworkLinkStepState = "source" | "target" | "valid" | "invalid";

function writeNetworkLinkStepState(element: HTMLElement | null, state: NetworkLinkStepState): void {
	if (!element) return;
	element.dataset.stage = state;
	for (const step of element.querySelectorAll<HTMLElement>("[data-step]")) {
		const kind = step.dataset.step;
		const current =
			(state === "source" && kind === "source") ||
			((state === "target" || state === "invalid") && kind === "target") ||
			(state === "valid" && kind === "commit");
		if (current) step.setAttribute("aria-current", "step");
		else step.removeAttribute("aria-current");
		if (kind === "target" && state === "invalid") step.setAttribute("aria-invalid", "true");
		else step.removeAttribute("aria-invalid");
	}
}

function rejectedNetworkLinkEvaluation(
	plan: RailNetworkLinkPlan,
	committedRevision: number,
): RailDraftEvaluation {
	const stale =
		plan.baseRevision !== committedRevision || plan.networkLink.placementCode === "stale";
	return Object.freeze({
		plan,
		baseRevision: plan.baseRevision,
		committedRevision,
		validationLevel: "exact",
		stale,
		failureCode: stale ? "stale" : null,
		topologyValid: false,
		valid: false,
		reason: plan.reason,
		paths: null,
		envelopes: null,
		conflictCells: Object.freeze([...plan.conflicts]),
		issues: Object.freeze([]),
		invalidatedPortIds: Object.freeze([]),
		candidateCommittedEnvelopePairs: 0,
		testedCommittedEnvelopePairs: 0,
	});
}

