		const rect = canvas.getBoundingClientRect();
		const pointer = lastPointerClientRef.current;
		const localX = pointer.valid ? pointer.x - rect.left : rect.width / 2;
		const localY = pointer.valid ? pointer.y - rect.top : rect.height / 2;
		const paletteWidth = Math.min(286, Math.max(220, rect.width - 24));
		const paletteHeight = 196;
		const left = Math.max(12, Math.min(rect.width - paletteWidth - 12, localX + 14));
		const top = Math.max(12, Math.min(rect.height - paletteHeight - 12, localY + 14));
		updateContextPalette(Object.freeze({ left, top }));
