				const usedHeapBytes = browserPerformance.memory?.usedJSHeapSize;
				if (usedHeapBytes !== undefined) renderPerformance.recordHeap(usedHeapBytes);
				const renderStats = rendererRef.current.getStats();
				const performanceStats = renderPerformance.snapshot();
				canvas.dataset.staticRedraws = String(renderStats.staticRedraws);
				canvas.dataset.overlayRedraws = String(renderStats.overlayRedraws);
				canvas.dataset.physicalBindings = String(renderStats.physicalPathBindings);
				canvas.dataset.physicalPaths = String(renderStats.physicalPathCount);
				canvas.dataset.cursorX = String(cursorCellRef.current.x);
				canvas.dataset.cursorY = String(cursorCellRef.current.y);
