function IconButton({
	label,
	disabled = false,
	exclusiveCommandScope,
	pressed,
	expanded,
	controls,
	buttonRef,
	tooltip,
	tone = "default",
	keyShortcuts,
	guidedTarget = false,
	touchTarget = false,
	onClick,
	children,
}: {
	label: string;
	disabled?: boolean;
	exclusiveCommandScope?: "project" | "view";
	pressed?: boolean;
	expanded?: boolean;
	controls?: string;
	buttonRef?: Ref<HTMLButtonElement>;
	tooltip?: string;
	tone?: "default" | "danger";
	keyShortcuts?: string;
	guidedTarget?: boolean;
	touchTarget?: boolean;
	onClick: (event: ReactMouseEvent<HTMLButtonElement>) => void;
	children: React.ReactNode;
}): React.ReactElement {
	return (
		<button
			ref={buttonRef}
			type="button"
			className="tilefab-icon-button"
			data-active={pressed}
			data-tone={tone}
			data-exclusive-command-scope={exclusiveCommandScope}
			data-guided-target={guidedTarget || undefined}
			data-touch-target={touchTarget || undefined}
			disabled={disabled}
			aria-label={label}
			aria-pressed={pressed}
			aria-expanded={expanded}
			aria-controls={controls}
			aria-keyshortcuts={keyShortcuts}
			title={tooltip ?? label}
			onClick={onClick}
		>
			{children}
		</button>
	);
}

function ToolButton({
	label,
	active,
	disabled = false,
	tone = "default",
	controls,
	expanded,
	keyShortcuts,
	caption,
	captionDescription,
	compactCaption,
	guidedCaption,
	guidedTarget = false,
	guidedActionId,
	guidedSelected = false,
	guidedDescriptionId,
	disclosure = false,
	onClick,
	children,
}: {
	label: string;
	active: boolean;
	disabled?: boolean;
	tone?: "default" | "danger";
	controls?: string;
	expanded?: boolean;
	keyShortcuts?: string;
	caption?: string;
	captionDescription?: string;
	compactCaption?: string;
	guidedCaption?: string;
	guidedTarget?: boolean;
	guidedActionId?: string;
	guidedSelected?: boolean;
	guidedDescriptionId?: string;
	disclosure?: boolean;
	onClick: (event: ReactMouseEvent<HTMLButtonElement>) => void;
	children: React.ReactNode;
}): React.ReactElement {
	const visibleCaption = guidedCaption ?? caption;
	return (
		<button
			type="button"
			className="tilefab-tool-button"
			data-active={active}
			data-guided-action-id={guidedActionId}
			data-guided-target={guidedTarget || undefined}
			data-compact-caption={compactCaption}
			data-tone={tone}
			disabled={disabled}
			aria-label={label}
			aria-describedby={guidedDescriptionId}
			aria-pressed={disclosure ? undefined : active}
			aria-controls={controls}
			aria-expanded={expanded}
			aria-keyshortcuts={keyShortcuts}
			title={label}
			onClick={onClick}
		>
			<span className="tilefab-tool-button-icon" aria-hidden="true">
				{children}
			</span>
			{compactCaption ? (
				<small className="tilefab-tool-button-compact-caption" aria-hidden="true">
					{compactCaption}
				</small>
			) : null}
			{visibleCaption ? (
				<span className="tilefab-tool-button-caption">
					<strong>{visibleCaption}</strong>
					<small>
						{guidedCaption
							? guidedSelected
								? "선택됨 · 캔버스에서 진행"
								: guidedTarget
									? "다음 단계 도구"
									: "완료한 도구"
							: captionDescription}
					</small>
				</span>
			) : null}
		</button>
	);
}

function ReadinessCheck({
	label,
	passed,
	state,
	value,
}: {
	label: string;
	passed?: boolean;
	state?: "pass" | "fail" | "pending";
	value: string;
}): React.ReactElement {
	const resolvedState = state ?? (passed ? "pass" : "fail");
	return (
		<div data-state={resolvedState}>
			<dt>
				{resolvedState === "pass" ? (
					<Check size={12} aria-hidden="true" />
				) : resolvedState === "pending" ? (
					<RefreshCcw size={12} aria-hidden="true" />
				) : (
					<AlertTriangle size={12} aria-hidden="true" />
				)}
				{label}
			</dt>
			<dd>{value}</dd>
		</div>
	);
}

function staticFabProjectCheckDomainLabel(domain: StaticFabProjectCheckDomain): string {
	if (domain === "switch") return "SWITCH";
	if (domain === "port") return "PORT";
	if (domain === "equipment") return "EQUIPMENT";
	if (domain === "organization") return "ORGANIZATION";
	return "HIERARCHY";
}

function staticFabProjectCheckLocationLabel(
	location: StaticFabProjectCheckLocation,
	occurrenceCount: number,
): string {
	const entity =
		location.kind === "project"
			? "PROJECT"
			: location.entityId > 0
				? `${location.kind.toUpperCase()}-${location.entityId}`
				: location.kind.toUpperCase();
	const { minX, minZ, maxX, maxZ } = location.bounds;
	const coordinate =
		maxX - minX <= 1 && maxZ - minZ <= 1
			? `X ${minX.toFixed(1)} · Z ${minZ.toFixed(1)}`
			: `X ${minX.toFixed(1)} TO ${maxX.toFixed(1)} · Z ${minZ.toFixed(1)} TO ${maxZ.toFixed(1)}`;
	const related =
		location.relatedKind && location.relatedEntityId > 0
			? ` ↔ ${location.relatedKind.toUpperCase()}-${location.relatedEntityId}`
			: "";
	const record = location.recordIndex >= 0 ? ` · RECORD ${location.recordIndex + 1}` : "";
	const relatedRecord =
		location.relatedRecordIndex >= 0 ? ` · PEER RECORD ${location.relatedRecordIndex + 1}` : "";
	const token = location.token ? ` · ${location.token.toUpperCase()}` : "";
	const occurrence = `CONFLICT ${location.occurrenceIndex + 1}/${occurrenceCount}`;
	const measurement = staticFabProjectCheckMeasurementLabel(location);
	return `${occurrence} · ${entity}${related}${record}${relatedRecord}${token} · ${coordinate}${measurement ? ` · ${measurement}` : ""}`;
}

function staticFabProjectCheckInspectorLabel(
	checks: StaticFabProjectChecks,
	location: StaticFabProjectCheckLocation,
	map: TileMap,
	portEquipment: PortEquipmentState,
	organizations: StaticFabOrganizationState,
): string | null {
	if (location.kind === "port") {
		if (staticFabProjectChecksHaveAmbiguousPortEquipmentIdentity(checks)) return null;
		const port = portEquipment.ports.find((candidate) => candidate.id === location.entityId);
		return port && portEquipment.equipmentGroups.some((group) => group.id === port.equipmentGroupId)
			? "OPEN PORT INSPECTOR"
			: null;
	}
	if (location.kind === "equipment") {
		if (staticFabProjectChecksHaveAmbiguousPortEquipmentIdentity(checks)) return null;
		const group = portEquipment.equipmentGroups.find(
			(candidate) => candidate.id === location.entityId,
		);
		return group?.portIds.some((portId) => portEquipment.ports.some((port) => port.id === portId))
			? "OPEN EQUIPMENT INSPECTOR"
			: null;
	}
	if (location.kind === "switch") return "OPEN SWITCH INSPECTOR";
	if (location.kind === "project") {
		return map.size > 0 ? "OPEN AREA INSPECTOR" : null;
	}
	if (location.kind === "rail") {
		const cell = staticFabProjectCheckRailCell(location);
		return cell && map.getEncoded(cell.x, cell.y) !== 0 ? "OPEN RAIL INSPECTOR" : null;
	}
	if (location.kind === "organization") {
		return staticFabProjectCheckOrganizationTarget(checks, location, organizations)
			? "OPEN ORGANIZATION"
			: null;
	}
	return null;
}

function staticFabProjectCheckCameraBounds(location: StaticFabProjectCheckLocation): {
	readonly minX: number;
	readonly minY: number;
	readonly maxX: number;
	readonly maxY: number;
} {
	const continuousWorldBounds = location.kind === "equipment";
	return {
		minX: location.bounds.minX,
		minY: location.bounds.minZ,
		maxX: continuousWorldBounds
			? location.bounds.maxX
			: Math.max(location.bounds.minX, location.bounds.maxX - 1),
		maxY: continuousWorldBounds
			? location.bounds.maxZ
			: Math.max(location.bounds.minZ, location.bounds.maxZ - 1),
	};
}

function staticFabProjectCheckRailCell(location: StaticFabProjectCheckLocation): Cell | null {
	const x = Math.floor(location.bounds.minX);
	const y = Math.floor(location.bounds.minZ);
	return Number.isSafeInteger(x) && Number.isSafeInteger(y) ? { x, y } : null;
}

function staticFabProjectCheckMeasurementLabel(
	location: StaticFabProjectCheckLocation,
): string | null {
	if (location.measurementUnit === "none" || location.measurementRelation === "none") return null;
	const suffix = location.measurementUnit === "millimeters" ? "mm" : "m";
	const measured =
		location.measuredValue === null
			? null
			: `${location.measuredValue.toLocaleString("en-US", { maximumFractionDigits: 2 })} ${suffix}`;
	const required =
		location.requiredValue === null
			? null
			: `${location.requiredValue.toLocaleString("en-US", { maximumFractionDigits: 2 })} ${suffix}`;
	if (location.measurementRelation === "minimum") {
		return measured && required
			? `${measured} · MIN ${required}`
			: required
				? `MIN ${required}`
				: measured;
	}
	if (location.measurementRelation === "maximum") {
		return measured && required
			? `${measured} · MAX ${required}`
			: required
				? `MAX ${required}`
				: measured;
	}
	if (location.measurementRelation === "exact") {
		return measured && required
			? `${measured} · TARGET ${required}`
			: required
				? `TARGET ${required}`
				: measured;
	}
	if (measured && required) return `OVERLAP ${measured} · MAX ${required}`;
	if (measured) return `OVERLAP ${measured}`;
	return required ? `MAX ${required}` : null;
}

function directionNames(mask: number): string {
	const names: string[] = [];
	for (const direction of ALL_DIRECTIONS) {
		if ((mask & direction) === 0) continue;
		if (direction === DIR_N) names.push("N");
		if (direction === DIR_E) names.push("E");
		if (direction === DIR_S) names.push("S");
		if (direction === DIR_W) names.push("W");
	}
	return names.length > 0 ? names.join(" + ") : "OPEN";
}

function portRouteSummary(port: PortRecord): string {
	const route = port.route;
	if (route.kind === "CARDINAL_CELL") return `X ${route.x} · Z ${route.z}`;
	return `SW-${route.switchId} · ${route.role}`;
}

function portRouteDetail(port: PortRecord): string {
	const route = port.route;
	if (route.kind === "CARDINAL_CELL") {
		return `CARDINAL CELL X ${route.x} · Z ${route.z} · ${directionNames(route.from)} TO ${directionNames(route.to)}`;
	}
	return `ADVANCED SWITCH ${route.switchId} · CLASS ${route.profileClass} · ${route.role} ${route.portIndex ?? "THROAT"} · SEGMENT ${route.segmentOrdinal}`;
}

function portTypeForTool(tool: EditorTool): PortType | null {
	if (tool === "ohb") return "OHB";
	if (tool === "eq") return "EQ";
	if (tool === "stk") return "STK";
	return null;
}

function resolvedRailModule(
	index: RailModuleOwnershipIndex | null,
	cell: Cell,
): RailModuleOwnership | null {
	if (!index) return null;
	const resolution = resolveRailModuleOwnership(index, cell);
	return resolution.status === "resolved" ? resolution.module : null;
}

function railAreaSelectionCellCount(selection: RailAreaSelection): number {
	const cells = new Set<string>();
	for (const ownership of selection.ownerships) {
		for (const cell of ownership.footprintCells) cells.add(cellKey(cell.x, cell.y));
	}
	return cells.size;
}

function railTemplateAttachmentGuideKey(
	revision: number,
	session: RailTemplateSession | null,
): string {
	if (!session || !isRailTemplateAttachmentId(session.id)) return "";
	const item = railTemplateCatalogItem(session.id);
	const dimensions = item.parameters
		.map((descriptor) => railTemplateParameterValue(session.parameters, descriptor.key))
		.join(",");
	return `${revision}:${session.id}:${session.pose.forward}:${session.pose.side}:${session.pose.flow ?? "forward"}:${dimensions}`;
}

function railTemplateAttachmentIntentIndexKey(
	revision: number,
	session: RailTemplateSession | null,
	lock: RailTemplatePoseLock,
): string {
	if (!session || !isRailTemplateAttachmentId(session.id)) return "";
	const item = railTemplateCatalogItem(session.id);
	const dimensions = item.parameters
		.map((descriptor) => railTemplateParameterValue(session.parameters, descriptor.key))
		.join(",");
	return `${revision}:${session.id}:${railTemplatePoseLockKey(lock)}:${dimensions}`;
}

function railTemplateCompositionIntentIndexKey(
	revision: number,
	session: RailTemplateSession | null,
	lock: RailTemplatePoseLock,
): string {
	if (!session || !isRailTemplateCompositionId(session.id)) return "";
	const item = railTemplateCatalogItem(session.id);
	const dimensions = item.parameters
		.map((descriptor) => railTemplateParameterValue(session.parameters, descriptor.key))
		.join(",");
	return `${revision}:${session.id}:${railTemplatePoseLockKey(lock)}:${dimensions}`;
}

function railTemplatePoseLockKey(lock: RailTemplatePoseLock): string {
	return `${Number(lock.forward)}${Number(lock.side)}${Number(lock.flow)}`;
}

function railTemplatePoseLockStatus(lock: RailTemplatePoseLock): string {
	const automaticAxes: string[] = [];
	if (!lock.forward) automaticAxes.push("회전");
	if (!lock.side) automaticAxes.push("SIDE");
	if (!lock.flow) automaticAxes.push("FLOW");
	return automaticAxes.length > 0 ? `${automaticAxes.join("/")} AUTO` : "회전/SIDE/FLOW 고정";
}

function railTemplateCompositionGuideKey(
	revision: number,
	session: RailTemplateSession | null,
): string {
	if (!session || !isRailTemplateCompositionId(session.id)) return "";
	const item = railTemplateCatalogItem(session.id);
	const dimensions = item.parameters
		.map((descriptor) => railTemplateParameterValue(session.parameters, descriptor.key))
		.join(",");
	return `${revision}:${session.id}:${session.pose.forward}:${session.pose.side}:${session.pose.flow ?? "forward"}:${dimensions}`;
}

function planActiveBuild(
	map: TileMap,
	start: Cell,
	current: Cell,
	preference: BendPreference,
	mode: RailBuildMode,
	span: RailModuleSpan,
	advancedSwitchProfile: AdvancedSwitchProfileClass = "A",
	preferredSide: RailModuleSide | null = null,
	explicitSide: RailModuleSide | null = null,
	stampSession: RailStampSession | null = null,
	areaStampSession: RailAreaStampSession | null = null,
	areaStampResolvedPose: RailAreaStampPose | null = null,
	templateSession: RailTemplateSession | null = null,
	networkLinkContext: RailNetworkLinkAnchorContext | null = null,
	planningLevel: "preview" | "exact" = "preview",
): RailConstructionPlan {
	if (stampSession) {
		return planRailModuleStamp(map, stampSession.template, start, stampSession.pose);
	}
	if (areaStampSession) {
		const pose = areaStampResolvedPose ?? areaStampSession.pose;
		if (
			planningLevel === "preview" &&
			areaStampSession.template.sourceEdgeCount > FACTORY_SCALE_BLUEPRINT_PREVIEW_EDGE_THRESHOLD
		) {
			return planRailAreaStampPreview(map, areaStampSession.template, start, pose);
		}
		if (areaStampSession.staticFabTemplate) {
			return planStaticFabBlueprintPlacement(
				map,
				areaStampSession.document.portEquipment,
				areaStampSession.document.getPatchSequence(),
				areaStampSession.staticFabTemplate,
				start,
				pose,
			);
		}
		return planRailAreaStamp(map, areaStampSession.template, start, pose);
	}
	if (templateSession) {
		return planRailTemplate(
			map,
			templateSession.id,
			start,
			templateSession.pose,
			templateSession.parameters,
		);
	}
	return planCatalogRailConstruction(map, start, current, mode, {
		bend: preference,
		span,
		advancedSwitchProfile,
		preferredSide,
		explicitSide,
		networkLinkContext,
	});
}

function clearDraftPreviewTelemetry(canvas: Readonly<{ dataset: DOMStringMap }> | null): void {
	if (!canvas) return;
	delete canvas.dataset.activePlanKind;
	delete canvas.dataset.draftPreviewValid;
	delete canvas.dataset.draftPreviewValidation;
	delete canvas.dataset.draftPreviewBaseRevision;
	delete canvas.dataset.draftPreviewIssues;
	delete canvas.dataset.draftPreviewConflictCells;
	delete canvas.dataset.draftPreviewEnvelopes;
	delete canvas.dataset.draftMetricLength;
	delete canvas.dataset.draftMetricDeltaX;
	delete canvas.dataset.draftMetricDeltaZ;
	delete canvas.dataset.draftMetricWidth;
	delete canvas.dataset.draftMetricDepth;
	delete canvas.dataset.networkLinkGhostMode;
	delete canvas.dataset.networkLinkPresentedRouteCells;
}

function isRailModulePlan(plan: DragState["plan"]): plan is RailModulePlan {
	return plan !== null && "moduleKind" in plan && plan.moduleKind !== "advanced-switch";
}

function writeTemplatePreviewTelemetry(
	canvas: HTMLCanvasElement | null,
	plan: RailDraftPlan | null,
	evaluation: RailDraftEvaluation | null,
	feedback: RailTemplatePlacementFeedback | null,
): void {
	if (!canvas) return;
	if (!plan || !isRailTemplatePlan(plan)) {
		delete canvas.dataset.templateValid;
		delete canvas.dataset.templatePlanValid;
		delete canvas.dataset.templatePlacementCode;
		delete canvas.dataset.templateFeedbackCode;
		delete canvas.dataset.templateFeedbackState;
		delete canvas.dataset.templateOccupied;
		delete canvas.dataset.templateReserved;
		delete canvas.dataset.templateReservedBounds;
		delete canvas.dataset.templateHandles;
		delete canvas.dataset.templateConnectors;
		delete canvas.dataset.templateConnectorSpan;
		delete canvas.dataset.templateConflicts;
		delete canvas.dataset.templateTopology;
		delete canvas.dataset.templateGeometry;
		return;
	}
	canvas.dataset.templateValid = String(feedback?.state === "ready" && evaluation?.valid === true);
	canvas.dataset.templatePlanValid = String(plan.valid);
	canvas.dataset.templatePlacementCode = plan.template.placementCode;
	canvas.dataset.templateFeedbackCode = feedback?.code ?? "";
	canvas.dataset.templateFeedbackState = feedback?.state ?? "blocked";
	canvas.dataset.templateOccupied = String(plan.template.occupiedCells.length);
	canvas.dataset.templateReserved = String(plan.template.hardReservedCells.length);
	canvas.dataset.templateReservedBounds = feedback
		? `${feedback.reservation.bounds.minX},${feedback.reservation.bounds.minY},${feedback.reservation.bounds.maxX},${feedback.reservation.bounds.maxY}`
		: "";
	canvas.dataset.templateHandles = String(feedback?.handles.length ?? 0);
	canvas.dataset.templateConnectors = String(feedback?.connectors.length ?? 0);
	canvas.dataset.templateConnectorSpan = String(feedback?.connectors[0]?.spanMeters ?? 0);
	canvas.dataset.templateConflicts = String(feedback?.conflictCellCount ?? 0);
	canvas.dataset.templateTopology = plan.template.topologyFingerprint;
	canvas.dataset.templateGeometry = plan.template.geometryFingerprint;
}

function writeTemplatePlacementFeedback(
	panel: HTMLElement | null,
	badge: HTMLSpanElement | null,
	summary: HTMLElement | null,
	reason: HTMLParagraphElement | null,
	handles: HTMLElement | null,
	reservation: HTMLElement | null,
	announcement: HTMLSpanElement | null,
	feedback: RailTemplatePlacementFeedback | null,
): void {
	if (!panel) return;
	if (!feedback) {
		panel.hidden = true;
		delete panel.dataset.code;
		delete panel.dataset.state;
		if (badge) badge.textContent = "";
		if (summary) summary.textContent = "";
		if (reason) reason.textContent = "";
		if (handles) handles.textContent = "";
		if (reservation) reservation.textContent = "";
		if (announcement) {
			announcement.textContent = "";
			delete announcement.dataset.key;
		}
		return;
	}

	panel.hidden = false;
	panel.dataset.code = feedback.code;
	panel.dataset.state = feedback.state;
	if (badge) badge.textContent = feedback.label;
	if (summary) summary.textContent = feedback.summary;
	if (reason) {
		reason.textContent =
			feedback.state === "ready" ? feedback.expected : `${feedback.reason} · ${feedback.expected}`;
	}
	const routeReuseCount = feedback.connectors.filter(
		(connector) => connector.kind === "route-reuse",
	).length;
	const sharedConnectors = feedback.connectors.filter(
		(connector) => connector.kind === "shared-trunk",
	);
	const sharedSpans = [...new Set(sharedConnectors.map((connector) => connector.spanMeters))].sort(
		(left, right) => right - left,
	);
	const terminalText = feedback.handles
		.map(
			(handle) =>
				`${handle.label} ${handle.cell.x},${handle.cell.y} ${directionNames(handle.travelDirection)}`,
		)
		.join(" · ");
	const connectorText = [
		routeReuseCount > 0 ? `${routeReuseCount} ROUTE REUSE` : null,
		sharedConnectors.length > 0
			? `${sharedConnectors.length} TRUNKS · ${sharedSpans.join("/")} m`
			: null,
	]
		.filter((label): label is string => label !== null)
		.join(" · ");
	const handleText = [terminalText, connectorText].filter(Boolean).join(" · ") || "NONE";
	if (handles) handles.textContent = handleText;
	const reservationText = `${feedback.reservation.widthMeters} x ${feedback.reservation.depthMeters} m · ${feedback.reservation.cellCount} cells${
		feedback.reservation.extraCellCount > 0
			? ` · +${feedback.reservation.extraCellCount} clearance`
			: ""
	}`;
	if (reservation) reservation.textContent = reservationText;
	if (announcement) {
		const semanticSignature = [
			...feedback.connectors.map(
				(connector) =>
					`${connector.id}:${connector.spanMeters}:${connector.travelDirection === null ? "ROUTE" : directionNames(connector.travelDirection)}`,
			),
			...feedback.handles.map(
				(handle) => `${handle.label}:${directionNames(handle.travelDirection)}`,
			),
			`${feedback.reservation.widthMeters}x${feedback.reservation.depthMeters}`,
			String(feedback.reservation.cellCount),
			String(feedback.reservation.extraCellCount),
		].join(":");
		const key = `${feedback.code}:${feedback.reason}:${semanticSignature}`;
		if (announcement.dataset.key !== key) {
			announcement.dataset.key = key;
			announcement.textContent = `${feedback.label}. ${feedback.summary}. ${feedback.reason}. ${handleText}. Reserved ${reservationText}`;
		}
	}
}

function isAdvancedSwitchPlan(plan: DragState["plan"]): plan is AdvancedSwitchPlan {
	return (
		plan !== null &&
		plan.kind === "build" &&
		"moduleKind" in plan &&
		plan.moduleKind === "advanced-switch"
	);
}

function nextBuildAnchor(plan: DragState["plan"], pointerEnd: Cell): Cell | null {
	if (isAdvancedSwitchPlan(plan) || isRailModulePlan(plan)) {
		return nextRailConstructionAnchor(
			{
				kind: "module",
				repeatFromExit: railConstructionCatalogItem(plan.moduleKind).repeatFromExit,
				exit: plan.exit,
			},
			pointerEnd,
		);
	}
	// Smart Route is direct manipulation: another drag begins where the user presses. Keeping its
	// committed endpoint as a hidden anchor makes a blank-area drag turn into an unexpected L-shaped
	// continuation. A deliberate click still establishes an anchor for click-then-click authoring.
	return nextRailConstructionAnchor({ kind: "direct-route" }, pointerEnd);
}

function portSlotStatusMessage(
	status: number,
	portType: PortType = "OHB",
	conflictingEquipmentGroupId = 0,
): string {
	if (status === PORT_SLOT_STATUS.LEGAL) return `${portType} 포트를 배치할 수 있습니다`;
	if (status === PORT_SLOT_STATUS.UNSAFE_APPROACH) {
		return "터미널, 커브 또는 스위치 접근 구간에는 포트를 배치할 수 없습니다";
	}
	if (status === PORT_SLOT_STATUS.PORT_OCCUPIED) {
		return conflictingEquipmentGroupId > 0
			? `STK-${conflictingEquipmentGroupId} 포트가 점유한 레일 구간입니다`
			: "이미 사용 중인 포트 슬롯입니다";
	}
	if (status === PORT_SLOT_STATUS.PORT_CLEARANCE_CONFLICT) {
		return conflictingEquipmentGroupId > 0
			? `STK-${conflictingEquipmentGroupId} 포트 주변의 최소 간격이 부족합니다`
			: "기존 포트와의 최소 간격이 부족합니다";
	}
	if (status === PORT_SLOT_STATUS.EQUIPMENT_BODY_CONFLICT) {
		return conflictingEquipmentGroupId > 0
			? `STK-${conflictingEquipmentGroupId}이 점유한 레일 구간입니다`
			: "기존 STK가 점유한 레일 구간입니다";
	}
	if (status === PORT_SLOT_STATUS.RAIL_CLEARANCE_CONFLICT) {
		return "인접 레일의 설치 여유 공간과 충돌합니다";
	}
	if (status === PORT_SLOT_STATUS.LAYOUT_INVALID) {
		return "레일 레이아웃 오류를 먼저 해결해야 합니다";
	}
	return "현재 물리 경로에 연결할 수 없는 포트 슬롯입니다";
}

function staticFabArrangementModeForKeyboardCode(code: string): StaticFabArrangementMode | null {
	const match = /^(?:Digit|Numpad)([1-5])$/.exec(code);
	if (!match) return null;
	return STATIC_FAB_ARRANGEMENT_MODES[Number(match[1]) - 1] ?? null;
}

function staticFabArrangementModeLabel(mode: StaticFabArrangementMode): string {
	switch (mode) {
		case "ALIGN_MIN":
			return "MIN";
		case "ALIGN_CENTER":
			return "CENTER";
		case "ALIGN_MAX":
			return "MAX";
		case "DISTRIBUTE_CENTERS":
			return "CENTERS";
		case "DISTRIBUTE_GAPS":
			return "GAPS";
	}
}

function staticFabArrangementModeDescription(mode: StaticFabArrangementMode): string {
	switch (mode) {
		case "ALIGN_MIN":
			return "선택 축의 최소 경계를 맞춥니다";
		case "ALIGN_CENTER":
			return "선택 축의 중심을 맞춥니다";
		case "ALIGN_MAX":
			return "선택 축의 최대 경계를 맞춥니다";
		case "DISTRIBUTE_CENTERS":
			return "첫 루트와 마지막 루트 사이의 중심 간격을 균등하게 만듭니다";
		case "DISTRIBUTE_GAPS":
			return "첫 루트와 마지막 루트 사이의 외곽 간격을 균등하게 만듭니다";
	}
}

function buildModeInstruction(mode: RailBuildMode, hasAnchor: boolean): string {
	const item = railConstructionCatalogItem(mode);
	if (mode === "network-link") {
		return hasAnchor
			? "다른 폐쇄 루프의 평행 직선 구간을 선택해 OUTBOUND와 RETURN을 함께 건설하세요"
			: "첫 번째 폐쇄 루프의 단방향 직선 구간을 선택하세요";
	}
	if (item.pointerIntent === "route-end") return RAIL_ROUTE_DRAG_STATUS;
	if (!hasAnchor) return "열린 종점 근처를 클릭하면 자석식으로 시작점이 맞춰집니다";
	return `${item.statusLabel} 방향을 왼쪽 또는 오른쪽에서 선택하세요`;
}

